// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.repositoryimport com.roshan.persona.brain.memory.EntityTypeimport com.roshan.persona.brain.memory.KgEntityimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.KgDaoimport com.roshan.persona.database.entity.KgEdgeEntityimport com.roshan.persona.database.entity.KgEntityEntityimport timber.log.Timberimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.AppError/** * NOUS — Knowledge Graph Repository. * * Manages KG entities (nodes) and edges (relationships). * Supports: entity lookup, alias search, edge traversal (N-hop), * temporal versioning, Bayesian confidence reinforcement. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§4 KG Design</a> */class KnowledgeGraphRepository(    private val dao: KgDao,) {    // ─── Entities ────────────────────────────────────────────────────    /**     * Find or create an entity by type + canonical name.     * If found, increments mention count.     */    suspend fun findOrCreateEntity(type: String, name: String, aliases: List<String> = emptyList()): Result<Long> {        return try {            val existing = dao.findEntity(type, name)            if (existing != null) {                dao.incrementMention(existing.id, System.currentTimeMillis())                Result.Success(existing.id, CorrelationId.generate(), 0)            } else {                val now = System.currentTimeMillis()                val entity = KgEntityEntity(                    type = type,                    canonicalName = name,                    aliases = if (aliases.isEmpty()) null else aliases.joinToString(","),                    metadata = null,                    confidenceAlpha = 1.0f,                    confidenceBeta = 0.0f,                    mentionCount = 1,                    lastMentioned = now,                    isDeleted = false,                    createdAt = now,                    updatedAt = now,                )                val id = dao.insertEntity(entity)                Result.Success(id, CorrelationId.generate(), 0)            }        } catch (e: Exception) {            Timber.e(e, "Failed to find/create KG entity")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Get entity by ID.     */    suspend fun getEntityById(id: Long): Result<KgEntityEntity?> {        return try { Result.Success(dao.getEntityById(id), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Find entities by alias (substring match).     */    suspend fun findByAlias(alias: String): Result<List<KgEntityEntity>> {        return try { Result.Success(dao.findByAlias(alias), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Get all entities of a specific type.     */    suspend fun getEntitiesByType(type: String): Result<List<KgEntityEntity>> {        return try { Result.Success(dao.getEntitiesByType(type), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Soft-delete an entity (tombstone).     */    suspend fun forgetEntity(id: Long): Result<Unit> {        return try { dao.softDeleteEntity(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun entityCount(): Int = try { dao.entityCount() } catch (e: Exception) { 0 }    /**     * Entity Resolution — merge duplicate entities (Strategy §3 "Entity resolution").     *     * Finds all entities of [type] whose canonical name or aliases match [name]     * (case-insensitive, Levenshtein distance ≤ [fuzzyThreshold]) and merges them     * into the single best entity (highest mention count).     *     * ## Merge process     *     * 1. Find candidate entities (same type, name matches or alias matches).     * 2. Pick the "primary" entity (highest mentionCount, tie-break: earliest createdAt).     * 3. For each "duplicate" entity:     *    a. Re-point all edges (source + target) to the primary.     *    b. Merge aliases (union of all aliases, excluding primary's canonical name).     *    c. Sum mention counts into primary.     *    d. Soft-delete the duplicate.     *     * @return the number of duplicates merged, or 0 if no duplicates found.     */    suspend fun resolveAndMergeEntities(type: String, name: String, fuzzyThreshold: Int = 2): Int {        return try {            // Find candidates: same type + name/alias matches.            val candidates = mutableListOf<KgEntityEntity>()            // Exact name match.            dao.findEntity(type, name)?.let { candidates.add(it) }            // Alias match.            candidates.addAll(dao.findByAlias(name).filter { it.type == type })            // Fuzzy match: Levenshtein distance ≤ threshold.            val allOfType = dao.getEntitiesByType(type)            for (entity in allOfType) {                if (entity in candidates) continue                val dist = levenshtein(entity.canonicalName.lowercase(), name.lowercase())                if (dist <= fuzzyThreshold) candidates.add(entity)            }            if (candidates.size < 2) return 0  // No duplicates.            // Pick primary: highest mentionCount, tie-break earliest createdAt.            val primary = candidates.sortedWith(                compareByDescending<KgEntityEntity> { it.mentionCount }                    .thenBy { it.createdAt },            ).first()            val duplicates = candidates.filter { it.id != primary.id }            Timber.tag(TAG).i("Merging ${duplicates.size} duplicate(s) into '${primary.canonicalName}' (id=${primary.id}).")            // Merge each duplicate into primary.            val mergedAliases = primary.aliases?.split(",")?.toMutableSet() ?: mutableSetOf()            var totalMentions = primary.mentionCount            val duplicateIds = duplicates.map { it.id }            val allOutgoing = if (duplicateIds.isNotEmpty()) dao.getOutgoingEdgesForEntities(duplicateIds) else emptyList()            val allIncoming = if (duplicateIds.isNotEmpty()) dao.getIncomingEdgesForEntities(duplicateIds) else emptyList()            val edgesToInsert = mutableListOf<com.roshan.persona.database.entity.KgEdgeEntity>()            for (edge in allOutgoing) {                edgesToInsert.add(edge.copy(sourceEntityId = primary.id))            }            for (edge in allIncoming) {                edgesToInsert.add(edge.copy(targetEntityId = primary.id))            }            if (edgesToInsert.isNotEmpty()) {                dao.insertEdges(edgesToInsert)            }            for (dup in duplicates) {                // Merge aliases.                dup.aliases?.split(",")?.forEach { alias ->                    val trimmed = alias.trim()                    if (trimmed.isNotEmpty() && trimmed != primary.canonicalName) {                        mergedAliases.add(trimmed)                    }                }                totalMentions += dup.mentionCount                // Soft-delete duplicate.                dao.softDeleteEntity(dup.id)            }            // Update primary with merged aliases + summed mentions.            // Use insertEntity with REPLACE strategy (same ID = update).            val now = System.currentTimeMillis()            dao.insertEntity(                primary.copy(                    aliases = if (mergedAliases.isEmpty()) null else mergedAliases.joinToString(","),                    mentionCount = totalMentions,                    updatedAt = now,                ),            )            duplicates.size        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Entity resolution failed for '$name' (type=$type)")            0        }    }    /**     * Levenshtein distance — number of single-char edits to transform [a] into [b].     */    private fun levenshtein(a: String, b: String): Int {        val dp = Array(a.length + 1) { IntArray(b.length + 1) }        for (i in 0..a.length) dp[i][0] = i        for (j in 0..b.length) dp[0][j] = j        for (i in 1..a.length) {            for (j in 1..b.length) {                val cost = if (a[i - 1] == b[j - 1]) 0 else 1                dp[i][j] = minOf(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost)            }        }        return dp[a.length][b.length]    }    // ─── Edges ───────────────────────────────────────────────────────    /**     * Create an edge between two entities.     * If an identical active edge exists, reinforce it instead.     */    suspend fun findOrCreateEdge(        sourceEntityId: Long,        targetEntityId: Long,        edgeType: String,        source: String,    ): Result<Long> {        return try {            val existing = dao.getOutgoingEdges(sourceEntityId)                .find { it.targetEntityId == targetEntityId && it.edgeType == edgeType }            if (existing != null) {                dao.reinforceEdge(existing.id)                Result.Success(existing.id, CorrelationId.generate(), 0)            } else {                val now = System.currentTimeMillis()                val edge = KgEdgeEntity(                    sourceEntityId = sourceEntityId,                    targetEntityId = targetEntityId,                    edgeType = edgeType,                    confidenceAlpha = 1.0f,                    confidenceBeta = 0.0f,                    validFrom = now,                    validTo = null,                    supersededBy = null,                    source = source,                    metadata = null,                    isDeleted = false,                    createdAt = now,                    updatedAt = now,                )                val id = dao.insertEdge(edge)                Result.Success(id, CorrelationId.generate(), 0)            }        } catch (e: Exception) {            Timber.e(e, "Failed to create KG edge")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Get all outgoing edges from an entity (1-hop traversal).     */    suspend fun getOutgoingEdges(entityId: Long): Result<List<KgEdgeEntity>> {        return try { Result.Success(dao.getOutgoingEdges(entityId), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Get all incoming edges to an entity (1-hop traversal).     */    suspend fun getIncomingEdges(entityId: Long): Result<List<KgEdgeEntity>> {        return try { Result.Success(dao.getIncomingEdges(entityId), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * N-hop traversal from a starting entity.     * Returns all reachable entity IDs within N hops.     */    suspend fun traverse(startEntityId: Long, maxHops: Int = 3): Result<Set<Long>> {        return try {            val visited = mutableSetOf<Long>()            val current = mutableSetOf(startEntityId)            for (hop in 0 until maxHops) {                val nextLevel = mutableSetOf<Long>()                for (entityId in current) {                    if (entityId in visited) continue                    visited.add(entityId)                    val outgoing = dao.getOutgoingEdges(entityId)                    for (edge in outgoing) {                        if (edge.targetEntityId !in visited) {                            nextLevel.add(edge.targetEntityId)                        }                    }                }                current.clear()                current.addAll(nextLevel)                if (current.isEmpty()) break            }            Result.Success(visited, CorrelationId.generate(), 0)        } catch (e: Exception) {            Timber.e(e, "KG traversal failed")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Reinforce an edge (positive evidence).     */    suspend fun reinforceEdge(id: Long): Result<Unit> {        return try { dao.reinforceEdge(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Contradict an edge (negative evidence).     */    suspend fun contradictEdge(id: Long): Result<Unit> {        return try { dao.contradictEdge(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Supersede an old edge with a new one (temporal versioning).     */    suspend fun supersedeEdge(oldId: Long, newId: Long): Result<Unit> {        return try { dao.supersedeEdge(oldId, newId, System.currentTimeMillis()); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    /**     * Soft-delete an edge (tombstone).     */    suspend fun forgetEdge(id: Long): Result<Unit> {        return try { dao.softDeleteEdge(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun edgeCount(): Int = try { dao.edgeCount() } catch (e: Exception) { 0 }    // ─── Conversion to Brain's KgEntity ──────────────────────────────    /**     * Convert DB entity to Brain's KgEntity for MemoryInterface.     */    fun toKgEntity(entity: KgEntityEntity, mentionedInSession: Boolean): KgEntity {        val type = runCatching { EntityType.valueOf(entity.type) }.getOrDefault(EntityType.CONCEPT)        val aliases = entity.aliases?.split(",")?.toSet() ?: emptySet()        return KgEntity(            id = entity.id.toString(),            type = type,            canonicalName = entity.canonicalName,            aliases = aliases,            mentionedInSession = mentionedInSession,        )    }    private companion object {        private const val TAG = "KgRepository"    }}
